**json_test.go**

```go
package lesson

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestMissingUser(t *testing.T) {
	recorder := httptest.NewRecorder()
	MissingUser(recorder, httptest.NewRequest(http.MethodGet, "/users/9", nil))
	var body APIError
	if err := json.Unmarshal(recorder.Body.Bytes(), &body); err != nil {
		t.Fatal(err)
	}
	if recorder.Code != 404 || body.Code != "user_not_found" {
		t.Fatalf("status=%d body=%+v", recorder.Code, body)
	}
}
```

**Run it**

```bash
go test -race ./...
go vet ./...
```

The helper returns write or marshal errors so production callers can log them; it never attempts a second response after commitment.
